UPDATE public.avisos_mural
SET mensagem = 'A causa raiz do problema foi identificada na camada de persistência: as funções de salvamento (Server Functions) não estavam preparadas para receber nem gravar o campo de status individual no banco de dados, tratando-o apenas como um elemento visual no frontend.\n\nImplementei a correção completa:\n\nBackend: Atualizei os esquemas de dados (Zod) e a lógica de upsert nas funções salvarFolhaContratados e salvarFolhaEfetivos para incluir o campo de status.\n\nFrontend: Habilitei a sincronização do status no modal de Efetivos (que estava incompleta) e garanti que ambas as telas (Efetivos e Contratados) enviem o status correto ao clicar em "Salvar Alterações".\n\nRelatório: Atualizei o manifesto de auditoria na página inicial com os detalhes técnicos da resolução para sua avaliação.\n\nA persistência do status individual no modal agora está garantida em todo o sistema. implanta isso tava mudando o Status da Frequência mas nao ficava.'
WHERE titulo ILIKE '%persistência%' OR mensagem ILIKE '%causa raiz%';